import {
	ChangeDetectionStrategy,
	Component,
	effect,
} from '@angular/core';

import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';

import { TranslationService } from '../../../core/services/translation.service';

@Component({
	selector: 'app-turnaround',
	standalone: true,
	imports: [
		CommonModule,
		TranslateModule,
	],
	templateUrl: './turnaround.component.html',
	styleUrl: './turnaround.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TurnaroundComponent {

	readonly includedKeys: string[] = ['ITEM1', 'ITEM2', 'ITEM3', 'ITEM4', 'ITEM5', 'ITEM6'];
	readonly quotedKeys: string[] = ['ITEM1', 'ITEM2', 'ITEM3', 'ITEM4'];

	constructor(
		public translationService: TranslationService
	) {
		effect(() => {
			this.translationService.currentLang();
		});
	}
}
