	addWebPageSchema() {
		const existingScript = this.document.getElementById('webpage-schema-graphics');
		if (existingScript) return;

		const script = this.document.createElement('script');
		script.type = 'application/ld+json';
		script.id = 'webpage-schema-graphics';
		script.textContent = JSON.stringify({
			'@context': 'https://schema.org',
			'@type': 'WebPage',
			name: 'Graphic Design Services',
			description: 'Unlimited high-quality graphic design services tailored for brands.',
			url: 'https://www.pixtar.ae/services/graphics',
		});

		this.document.head.appendChild(script);
	}

