	getFaqsData() {
		const obj = {
			type: 'Graphics',
		};
		this.faqService.getFaqs(obj).subscribe((res: any) => {
			if (res.code == 200) {
				this.graphicsFaqs = res?.result;
				this.addFaqSchema();

				this.cdr.markForCheck();
			}
		});
	}
	getTestimonialsData() {
		const obj = {
			type: 'graphics',
		};
		this.testimonialService.getAlltestimonial(obj).subscribe((res: any) => {
			if (res.code == 200) {
				this.graphicsTestimonials = res?.result?.filter((item: any) =>
					item.categorydata?.some((cat: any) => cat.name?.toLowerCase() === 'graphics'),
				);
				this.cdr.markForCheck();
			}
		});
	}
